ON CONFLICT (id) DO UPDATE SET organization_id = EXCLUDED.organization_id, name = EXCLUDED.name, description = EXCLUDED.description, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, created_at = EXCLUDED.created_at;

ON CONFLICT (id) DO UPDATE SET organization_id = EXCLUDED.organization_id, name = EXCLUDED.name, serial_number = EXCLUDED.serial_number, model = EXCLUDED.model, installed_at = EXCLUDED.installed_at, created_at = EXCLUDED.created_at;

ON CONFLICT (id) DO UPDATE SET device_id = EXCLUDED.device_id, status = EXCLUDED.status, started_at = EXCLUDED.started_at, ended_at = EXCLUDED.ended_at;

ON CONFLICT (id) DO UPDATE SET device_id = EXCLUDED.device_id, location_id = EXCLUDED.location_id, started_at = EXCLUDED.started_at, ended_at = EXCLUDED.ended_at;

ON CONFLICT (id) DO UPDATE SET device_id = EXCLUDED.device_id, variable = EXCLUDED.variable, value = EXCLUDED.value, unit = EXCLUDED.unit, recorded_at = EXCLUDED.recorded_at, created_at = EXCLUDED.created_at;
